function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (!nums.every(v => Number.isInteger(v) && v >= 1 && v <= 100)) return 'Each value in nums is a whole number from 1 to 100.';
  if (!Number.isInteger(k) || k < 1 || k > 100) return 'k is a whole number from 1 to 100.';
  return null;
}

