function maximizeSum(nums, k) {
  let largest = 0;
  for (const value of nums) {
    largest = Math.max(largest, value);
  }

  let score = 0;
  for (let move = 0; move < k; move++) {
    score += largest;
    largest++;
  }
  return score;
}

