function maximizeSum(nums, k) {
  // Play the moves on a copy of the array, always taking the current maximum.
  const values = [...nums];
  let score = 0;
  for (let move = 0; move < k; move++) {
    let at = 0;
    for (let i = 1; i < values.length; i++) if (values[i] > values[at]) at = i;
    const m = values[at];
    values.splice(at, 1);
    values.push(m + 1);
    score += m;
  }
  return score;
}

